}

// â”€â”€ Force simulation â”€â”€
function runForceSimulation(
    nodes: GraphNode[],
    edges: GraphEdge[],
    width: number,
    height: number,
    iterations: number = 120,
    style: 'force' | 'maltego' | 'tree' = 'force'
) {
    const nodeMap = new Map(nodes.map(n => [n.id, n]));
    const REPULSION = style === 'maltego' ? 5000 : 3500;
    const ATTRACTION = style === 'maltego' ? 0.015 : 0.008;
    const DAMPING = 0.85;
    const CENTER_GRAVITY = 0.01;
    const cx = width / 2;
    const cy = height / 2;

    for (let iter = 0; iter < iterations; iter++) {
        const temp = 1 - iter / iterations; // cooling

        // Repulsion (all pairs)
        for (let i = 0; i < nodes.length; i++) {
            for (let j = i + 1; j < nodes.length; j++) {
                const a = nodes[i], b = nodes[j];
                let dx = b.x - a.x;
                let dy = b.y - a.y;
                let dist = Math.sqrt(dx * dx + dy * dy) || 1;
                const force = (REPULSION * temp) / (dist * dist);
                const fx = (dx / dist) * force;
                const fy = (dy / dist) * force;
                if (!a.pinned) { a.vx -= fx; a.vy -= fy; }
                if (!b.pinned) { b.vx += fx; b.vy += fy; }
            }
        }

        // Attraction (edges)
        for (const edge of edges) {
            const a = nodeMap.get(edge.source);
            const b = nodeMap.get(edge.target);
            if (!a || !b) continue;
            let dx = b.x - a.x;
            let dy = b.y - a.y;
            let dist = Math.sqrt(dx * dx + dy * dy) || 1;
            const force = dist * ATTRACTION * temp;
            const fx = (dx / dist) * force;
            const fy = (dy / dist) * force;
            if (!a.pinned) { a.vx += fx; a.vy += fy; }
            if (!b.pinned) { b.vx -= fx; b.vy -= fy; }
        }

        // Center gravity
        for (const n of nodes) {
            if (n.pinned) continue;
            n.vx += (cx - n.x) * CENTER_GRAVITY * temp;
            n.vy += (cy - n.y) * CENTER_GRAVITY * temp;
        }

        // Apply velocities
        for (const n of nodes) {
            if (n.pinned) continue;
            n.vx *= DAMPING;
            n.vy *= DAMPING;
            n.x += n.vx;
            n.y += n.vy;
            // Keep in bounds
            n.x = Math.max(40, Math.min(width - 40, n.x));
            n.y = Math.max(40, Math.min(height - 40, n.y));
        }
    }
}

