    /// Parse the parameter count (in billions) from a model name like "qwen3:30b" â†’ 30.
    /// Returns None if not found. Used for smarter context/tool decisions.
    fn parse_model_param_count(model: &str) -> Option<u32> {
        // Try to find a pattern like ":30b", ":7b", ":72b", "30b-", "7b-" etc.
        let m = model.to_lowercase();
        // Look for number followed by 'b' (optionally preceded by ':' or '-')
        let re_parts: Vec<&str> = m.split(|c| c == ':' || c == '-' || c == '_' || c == '/').collect();
        for part in re_parts {
            // Strip leading non-digits and trailing non-digits to extract e.g. "30b" â†’ 30
            let digits: String = part.chars().take_while(|c| c.is_ascii_digit()).collect();
            let suffix: String = part.chars().skip(digits.len()).collect();
            if suffix.starts_with('b') && !digits.is_empty() {
                if let Ok(n) = digits.parse::<u32>() {
                    return Some(n);
                }
            }
        }
        None
    }

    /// Returns whether a model is "small" (â‰¤ 15B params) based on its name.
    /// This is used to decide prompt complexity, tool count, context limits.
    fn is_small_model_name(model: &str) -> bool {
        let m = model.to_lowercase();
        // Explicit tiny suffixes
        if m.contains("mini") || m.contains("tiny") || m.contains("0.5b") || m.contains("1.5b") {
            return true;
        }
        
        // Gemma4 "effective" params (e2b, e4b) are MoE models. While their total parameter 
        // count is high, their active parameters and footprint allow them to run like small models.
        // We WANT them to use the fast, optimized prompt.
        if (m.contains("gemma4") || m.contains("gemma-4")) && (m.contains("e2b") || m.contains("e4b") || m.contains("2b") || m.contains("4b")) {
            return true;
        }
        
        // Parse parameter count: â‰¤ 14B â†’ small
        // This covers the user's primary local fleet: 3b, 7b, 8b, 9b, 14b.
        if let Some(n) = Self::parse_model_param_count(&m) {
            return n <= 14;
        }
        false
    }

